# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                  // Maximum connections in pool
  min: 2,                   // Minimum idle connections maintained

  // Timeout settings (all in milliseconds)
  connectionTimeoutMillis: 5000,   // Wait time to acquire connection from pool
  idleTimeoutMillis: 30000,        // Remove idle connections after this time
  query_timeout: 10000,            // Abort queries running longer than this
  statement_timeout: 10000,        // PostgreSQL-level statement timeout
  idle_in_transaction_session_timeout: 30000, // Kill idle transactions

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production' ? {
    rejectUnauthorized: true,
    ca: process.env.DB_SSL_CERT,
  } : false,
});

module.exports = pool;
```

## Error Handling & Monitoring

```javascript
// db/pool.js (continued)
const { Pool } = require('pg');

class DatabasePool {
  constructor() {
    this.pool = new Pool({ /* config above */ });
    this._attachEventHandlers();
  }

  _attachEventHandlers() {
    // Fired when a new client is created
    this.pool.on('connect', (client) => {
      console.log('New client connected to pool');
      client.query('SET timezone = "UTC"'); // Per-connection setup
    });

    // Fired when a client is acquired from the pool
    this.pool.on('acquire', (client) => {
      console.debug(`Client acquired | Pool size: ${this.pool.totalCount}`);
    });

    // CRITICAL: handle idle client errors to prevent pool crashes
    this.pool.on('error', (err, client) => {
      console.error('Unexpected error on idle client:', err);
      // Do NOT throw here — log and let the pool recover
    });

    // Fired when a client is removed from the pool
    this.pool.on('remove', (client) => {
      console.log('Client removed from pool');
    });
  }

  // Pool health metrics
  getStats() {
    return {
      total: this.pool.totalCount,
      idle: this.pool.idleCount,
      waiting: this.pool.waitingCount,
    };
  }
}
```

## Query Helpers with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Simple query — use for most read/write operations
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    if (duration > 1000) {
      console.warn('Slow query detected:', { text, duration, rows: result.rowCount });
    }

    return result;
  } catch (err) {
    console.error('Query failed:', { text, params, error: err.message });
    throw enrichError(err);
  }
}

/**
 * Transaction — use when multiple queries must succeed or fail together
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Always release back to pool
  }
}

/**
 * Manual client checkout — use for long-running or multi-step operations
 */
async function withClient(callback) {
  const client = await pool.connect();

  try {
    return await callback(client);
  } finally {
    client.release();
  }
}

/**
 * Map PostgreSQL error codes to meaningful errors
 */
function enrichError(err) {
  const errorMap = {
    '23505': { type: 'UniqueViolation',      message: 'Record already exists' },
    '23503': { type: 'ForeignKeyViolation',  message: 'Referenced record not found' },
    '23502': { type: 'NotNullViolation',     message: 'Required field is missing' },
    '42P01': { type: 'UndefinedTable',       message: 'Table does not exist' },
    '57014': { type: 'QueryCanceled',        message: 'Query timed out' },
    '53300': { type: 'TooManyConnections',   message: 'Connection pool exhausted' },
  };

  const mapped = errorMap[err.code];
  if (mapped) {
    const enriched = new Error(mapped.message);
    enriched.type = mapped.type;
    enriched.originalError = err;
    return enriched;
  }

  return err;
}

module.exports = { query, withTransaction, withClient };
```

## Usage Examples

```javascript
// routes/users.js
const { query, withTransaction } = require('../db/query');

// Simple query
async function getUser(id) {
  const { rows } = await query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    const { rows: [sender] } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (sender.balance < amount) {
      throw new Error('Insufficient funds'); // Triggers ROLLBACK
    }

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    return { success: true };
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`${signal} received — shutting down gracefully`);

  try {
    await pool.end(); // Wait for active queries to finish, then close all connections
    console.log('Pool closed successfully');
    process.exit(0);
  } catch (err) {
    console.error('Error during pool shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5–10 | 20–100 (tune per load) |
| `connectionTimeoutMillis` | 5000 | 5000 |
| `idleTimeoutMillis` | 10000 | 30000 |
| `query_timeout` | 30000 | 5000–10000 |
| `ssl` | false | true |

**Critical rules to follow:**
- Always `release()` clients in a `finally` block
- Never throw inside the `pool.on('error')` handler
- Use `FOR UPDATE` in transactions to prevent race conditions
- Monitor `pool.waitingCount` — spikes indicate you need more connections or slower queries
